def feature_defaults(cfg):
    columns = [c for c in LEGACY_COLUMNS if cfg.high_gamma_band is not None or 'high_gamma' not in c]
    columns += [f'{prefix}_welch_{suffix}' for prefix in ('baseline','early','sustained') for suffix in ('nperseg','noverlap')]
    columns += ['feature_schema_version', 'source_csv_row', 'source_event_index',
                'pain_rating', 'pain_rating_status', 'pain_rating_source_csv_row']
    for prefix in ('early', 'sustained'):
        for label in ('paf', 'permutation_entropy'):
            columns += [f'{prefix}_{label}_{suffix}' for suffix in
                        ('channel_masks_equal', 'baseline_channel_indices', 'response_channel_indices')]
    for c in ('n1', 'n2_cz', 'p2_cz'):
        columns += [f'lep_{c}_error', f'lep_peak_{c}_error']
    for prefix in ('lep_gaussian', 'lep_reconstruction'):
        for c in ('n1', 'n2_cz', 'p2_cz', 'n2_p2_cz'):
            columns += [f'{prefix}_{c}_{suffix}' for suffix in
                        (('amplitude_uv', 'valid', 'reason') if c == 'n2_p2_cz' else
                         ('amplitude_uv', 'latency_ms', 'valid', 'reason'))]
    defaults = dict.fromkeys(columns, np.nan)
    for key in defaults:
        if key.endswith(('_valid', '_quality', '_channel_masks_equal')):
            defaults[key] = False
    from .tfr import TFRConfig, empty_tfr_row
    tfr = TFRConfig(**cfg.tfr)
    if tfr.enabled:
        defaults.update(empty_tfr_row(tfr))
    defaults['feature_schema_version'] = '2.1'
    return defaults
